import { useMutation } from '@tanstack/react-query';
import { exchangeResponseDTO } from '~/entities/exchange/api/dtos/types';
import { exchangeApi } from '~/entities/exchange/api/exchange-api';
import { CBDCAxiosError } from '~/shared/@types/error';
import { MutationOptions } from '~/shared/@types/query';

export const useConvertToTokenExecuteTrnscMutation = (
  options?: MutationOptions<string, CBDCAxiosError, exchangeResponseDTO>,
) => {
  const executeTrnsc = (id: string) => {
    //임시 parameter
    return exchangeApi.convertToTokenExecuteTrnsc(id);
  };

  const mutation = useMutation<exchangeResponseDTO, CBDCAxiosError, string>({
    ...options,
    mutationFn: (id: string) => executeTrnsc(id),
  });

  return {
    ...mutation,
  };
};
